#!/usr/bin/env node
/**
 * Copy the python-precompiled .gz lists into the static asset output so they
 * are served from /data/<name>.gz without invoking the Worker.
 *
 * The lists are generated by the python-precompiled workflow and uploaded to
 * R2 (`mise-versions-data/tools/<name>.gz`), which the Worker serves at
 * /tools/<name>.gz. This downloads those exact bytes through that route, so
 * the static copies are byte-identical and need no extra credentials. One
 * file exists per docs/python-precompiled*.toml (the same platform list
 * scripts/python-precompiled.sh writes both from).
 *
 * Usage: node scripts/fetch-python-precompiled-assets.js [outputDir]
 *   outputDir defaults to web/dist/client/data (run after the web build,
 *   which clears web/public/data).
 *
 * Environment:
 *   PYTHON_PRECOMPILED_SOURCE_URL  Optional; defaults to https://mise-versions.jdx.dev
 */

import { mkdirSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const SCRIPT_PATH = fileURLToPath(import.meta.url);
const REPO_ROOT = join(dirname(SCRIPT_PATH), "..");
const DEFAULT_SOURCE_URL = "https://mise-versions.jdx.dev";
const ATTEMPTS = 4;
const CONCURRENCY = 8;

export function pythonPrecompiledNames(docsDir) {
  return readdirSync(docsDir)
    .filter((file) => /^python-precompiled(-[\w-]+)?\.toml$/.test(file))
    .map((file) => file.replace(/\.toml$/, ""))
    .sort();
}

function isGzip(buffer) {
  return buffer.length >= 2 && buffer[0] === 0x1f && buffer[1] === 0x8b;
}

// Returns the file's bytes, or null if the source has no such file (a stale
// TOML for a platform whose list was never uploaded).
export async function fetchGz(sourceUrl, name, { attempts = ATTEMPTS } = {}) {
  const url = `${sourceUrl.replace(/\/+$/, "")}/tools/${name}.gz`;
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      const response = await fetch(url, {
        headers: { "Accept-Encoding": "identity" },
        signal: AbortSignal.timeout(30_000),
      });
      if (response.status === 404) return null;
      if (!response.ok) {
        throw new Error(`${url}: HTTP ${response.status}`);
      }
      const buffer = Buffer.from(await response.arrayBuffer());
      if (!isGzip(buffer)) throw new Error(`${url}: response is not gzip`);
      return buffer;
    } catch (error) {
      lastError = error;
      if (attempt < attempts) {
        await new Promise((r) => setTimeout(r, 1000 * 2 ** (attempt - 1)));
      }
    }
  }
  throw lastError;
}

export async function fetchPythonPrecompiledAssets({
  docsDir = join(REPO_ROOT, "docs"),
  outputDir = join(REPO_ROOT, "web", "dist", "client", "data"),
  sourceUrl = process.env.PYTHON_PRECOMPILED_SOURCE_URL || DEFAULT_SOURCE_URL,
  attempts = ATTEMPTS,
} = {}) {
  const names = pythonPrecompiledNames(docsDir);
  if (!names.includes("python-precompiled")) {
    throw new Error(`docs/python-precompiled.toml not found in ${docsDir}`);
  }
  mkdirSync(outputDir, { recursive: true });

  const written = [];
  const missing = [];
  let next = 0;
  const worker = async () => {
    while (next < names.length) {
      const name = names[next++];
      const buffer = await fetchGz(sourceUrl, name, { attempts });
      if (!buffer) {
        missing.push(name);
        continue;
      }
      writeFileSync(join(outputDir, `${name}.gz`), buffer);
      written.push(name);
    }
  };
  await Promise.all(Array.from({ length: CONCURRENCY }, () => worker()));

  if (!written.includes("python-precompiled")) {
    throw new Error("python-precompiled.gz is missing from the source");
  }
  return { written: written.sort(), missing: missing.sort() };
}

if (process.argv[1] && resolve(process.argv[1]) === SCRIPT_PATH) {
  const [outputDir] = process.argv.slice(2);
  fetchPythonPrecompiledAssets(outputDir ? { outputDir } : {})
    .then(({ written, missing }) => {
      console.log(`Wrote ${written.length} python-precompiled .gz assets`);
      if (missing.length > 0) {
        console.warn(`::warning::Not found at source: ${missing.join(", ")}`);
      }
    })
    .catch((error) => {
      console.error(error);
      process.exit(1);
    });
}
